def maxStability(n, edges, k):
    def make_dsu():
        return list(range(n))

    def find(p, x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(p, a, b):
        ra, rb = find(p, a), find(p, b)
        if ra == rb:
            return False
        p[ra] = rb
        return True

    # mandatory edges must be acyclic
    p0 = make_dsu()
    min_must = float("inf")
    for u, v, s, must in edges:
        if must:
            if not union(p0, u, v):
                return -1
            min_must = min(min_must, s)

    optional = [(u, v, s) for u, v, s, must in edges if not must]

    def feasible(S):
        p = make_dsu()
        comps = n
        for u, v, s, must in edges:
            if must:
                union(p, u, v)
                comps -= 1
        # free optional edges first
        for u, v, s in optional:
            if s >= S and union(p, u, v):
                comps -= 1
        used = 0
        for u, v, s in optional:
            if s < S <= 2 * s and union(p, u, v):
                comps -= 1
                used += 1
                if used > k:
                    return False
        return comps == 1

    if not feasible(1):
        return -1
    lo = 1
    hi = min(min_must, 2 * max(e[2] for e in edges))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
